{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Who owns Omaxe?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Omaxe Limited was founded by Rohtas Goel, who started it as a construction and contracting business in 1987; it was incorporated in 1989 as Omaxe Builders Pvt Ltd and listed on the stock market in 2007 (Wikipedia (archived copy)). Mohit Goel is its Managing Director (NBM&CW, 30 Apr 2026)."
      }
    },
    {
      "@type": "Question",
      "name": "What are Omaxe's projects in Lucknow?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Omaxe lists 17 residential and 4 commercial projects in Lucknow (Omaxe Lucknow page). The best known are Omaxe City (140 acres of plots and villas, delivered) and the 690-acre Omaxe Metro City township on Raebareli Road, where Omaxe Cassia is now being built (Omaxe City page, NBM&CW, 30 Apr 2026)."
      }
    },
    {
      "@type": "Question",
      "name": "Is Omaxe financially stable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Omaxe Ltd reported consolidated net losses of ₹685.40 crore in FY 2024-25 and ₹696.80 crore in FY 2025-26 (FY26 results report). In April–June 2026 it reported a small consolidated profit of ₹1.30 crore, while the parent company on its own still made a loss (Q1 FY27 results report, 12 Aug 2026). Buyers should judge each project by its RERA progress and construction on site."
      }
    },
    {
      "@type": "Question",
      "name": "When will Omaxe Cassia be completed?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Both Cassia phases are registered with UP RERA until 8 April 2029 (RERA record, RERA record). In April 2026 Omaxe said it expected to complete the project in about three years (NBM&CW, 30 Apr 2026)."
      }
    },
    {
      "@type": "Question",
      "name": "Who is the RERA promoter of Omaxe Cassia?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Omaxe Garv Buildtech Private Limited (formerly Garv Buildtech Private Limited), a wholly owned subsidiary of Omaxe Ltd (RERA record, NBM&CW, 30 Apr 2026). Your agreement should name this company."
      }
    },
    {
      "@type": "Question",
      "name": "Where is Omaxe Metro City?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "On Raebareli Road, Lucknow; Omaxe describes it as a 690-acre township (NBM&CW, 30 Apr 2026). RERA lists its Cassia phases in Sarojini Nagar tehsil (RERA record)."
      }
    }
  ]
}
